using Full.NET.Data.Abstractions;

namespace Full.NET.Modules.Ai.Persistence;

/// <summary>索引租约独立于上传租约；每次获权或写回均在 AI 权威行上核对当前版本。</summary>
internal static class AiKnowledgeIndexTaskSql
{
    internal const string Host = "knowledge.TenantId IS NULL";
    internal const string Tenant = "knowledge.TenantId = @TenantId";
    private const string Owner = "document.Id = @DocumentId AND document.KnowledgeBaseId = @KnowledgeBaseId AND knowledge.OwnerUserId = @OwnerUserId AND ";
    private const string Source = "version.DocumentId = document.Id AND version.Id = @VersionId AND document.IsDeleted = 0 AND knowledge.IsEnabled = 1 AND document.Version = @DocumentVersion AND knowledge.Version = @KnowledgeBaseVersion AND model.Id = knowledge.EmbeddingModelConfigId AND model.Version = knowledge.EmbeddingModelVersion AND model.IsEnabled = 1 AND (model.TenantId IS NULL OR model.TenantId = knowledge.TenantId) AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_version AS newer WHERE newer.DocumentId = document.Id AND newer.VersionNumber > version.VersionNumber) AND EXISTS (SELECT 1 FROM fn_ai_knowledge_import AS operation WHERE operation.VersionId = version.Id AND operation.DocumentId = document.Id AND operation.FileId = version.FileId AND operation.StateKey = 'completed')";
    private const string Enqueue = "INSERT INTO fn_ai_knowledge_index_task (Id, DocumentId, VersionId, DocumentVersion, KnowledgeBaseVersion, ModelConfigId, ModelConfigVersion, StateKey, AttemptCount, CreatedAtUtc, UpdatedAtUtc) SELECT @TaskId, document.Id, version.Id, document.Version, knowledge.Version, model.Id, model.Version, 'queued', 0, @Now, @Now FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id = document.KnowledgeBaseId INNER JOIN fn_ai_knowledge_version AS version ON version.DocumentId = document.Id INNER JOIN fn_ai_model_config AS model ON model.Id = knowledge.EmbeddingModelConfigId WHERE " + Owner;
    internal const string OwnerExists = " AND EXISTS (SELECT 1 FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id = document.KnowledgeBaseId WHERE document.Id = fn_ai_knowledge_index_task.DocumentId AND " + Owner;
    // 模型和来源版本来自持久化任务，不接受执行者用新版本覆盖旧批准。
    internal const string Live = " AND fn_ai_knowledge_index_task.VersionId = @VersionId AND fn_ai_knowledge_index_task.DocumentVersion = @DocumentVersion AND fn_ai_knowledge_index_task.KnowledgeBaseVersion = @KnowledgeBaseVersion" + CurrentAuthority;
    internal const string CurrentAuthority = " AND document.IsDeleted = 0 AND knowledge.IsEnabled = 1 AND document.Version = fn_ai_knowledge_index_task.DocumentVersion AND knowledge.Version = fn_ai_knowledge_index_task.KnowledgeBaseVersion AND knowledge.EmbeddingModelConfigId = fn_ai_knowledge_index_task.ModelConfigId AND knowledge.EmbeddingModelVersion = fn_ai_knowledge_index_task.ModelConfigVersion AND EXISTS (SELECT 1 FROM fn_ai_model_config AS model WHERE model.Id = fn_ai_knowledge_index_task.ModelConfigId AND model.Version = fn_ai_knowledge_index_task.ModelConfigVersion AND model.IsEnabled = 1 AND (model.TenantId IS NULL OR model.TenantId = knowledge.TenantId)) AND EXISTS (SELECT 1 FROM fn_ai_knowledge_version AS version WHERE version.Id = fn_ai_knowledge_index_task.VersionId AND version.DocumentId = document.Id AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_version AS newer WHERE newer.DocumentId = document.Id AND newer.VersionNumber > version.VersionNumber) AND EXISTS (SELECT 1 FROM fn_ai_knowledge_import AS operation WHERE operation.VersionId = version.Id AND operation.DocumentId = document.Id AND operation.FileId = version.FileId AND operation.StateKey = 'completed'))";
    private const string Acquire = "UPDATE fn_ai_knowledge_index_task SET StateKey = 'running', AttemptCount = AttemptCount + 1, LeaseToken = @LeaseToken, LeaseExpiresAtUtc = @LeaseExpiresAtUtc, FailureCode = NULL, UpdatedAtUtc = @Now WHERE Id = @TaskId AND AttemptCount < 3 AND (StateKey = 'queued' OR (StateKey = 'running' AND LeaseExpiresAtUtc <= @Now)) AND @LeaseExpiresAtUtc > @Now" + OwnerExists;
    private const string Held = " WHERE Id = @TaskId AND StateKey = 'running' AND LeaseToken = @LeaseToken AND LeaseExpiresAtUtc > @Now";
    private const string Renew = "UPDATE fn_ai_knowledge_index_task SET LeaseExpiresAtUtc = @LeaseExpiresAtUtc, UpdatedAtUtc = @Now" + Held + " AND @LeaseExpiresAtUtc > LeaseExpiresAtUtc" + OwnerExists;
    private const string Fail = "UPDATE fn_ai_knowledge_index_task SET StateKey = 'failed', FailureCode = @FailureCode, LeaseToken = NULL, LeaseExpiresAtUtc = NULL, UpdatedAtUtc = @Now" + Held + OwnerExists;
    private const string Retry = "UPDATE fn_ai_knowledge_index_task SET StateKey = 'queued', AttemptCount = 0, FailureCode = NULL, LeaseToken = NULL, LeaseExpiresAtUtc = NULL, UpdatedAtUtc = @Now WHERE Id = @TaskId AND (StateKey = 'failed' OR (StateKey = 'running' AND AttemptCount = 3 AND LeaseExpiresAtUtc <= @Now))" + OwnerExists;
    // 删除或禁用后仍允许所有者取消；终止状态不依赖一个已失效的批准快照。
    private const string Cancel = "UPDATE fn_ai_knowledge_index_task SET StateKey = 'cancelled', FailureCode = 'ai.knowledge.index_cancelled', LeaseToken = NULL, LeaseExpiresAtUtc = NULL, UpdatedAtUtc = @Now WHERE Id = @TaskId AND StateKey <> 'cancelled'" + OwnerExists;
    private const string Columns = "task.Id, task.DocumentId, task.VersionId, task.DocumentVersion, task.KnowledgeBaseVersion, task.ModelConfigId, task.ModelConfigVersion, task.StateKey, task.AttemptCount, task.FailureCode, task.LeaseToken, task.LeaseExpiresAtUtc, task.CreatedAtUtc, task.UpdatedAtUtc";
    private const string Read = "SELECT " + Columns + " FROM fn_ai_knowledge_index_task AS task INNER JOIN fn_ai_knowledge_document AS document ON document.Id = task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id = document.KnowledgeBaseId WHERE " + Owner;

    // 单次判定同时复核租约、来源和批准；只读 AI 自有元数据，不调用 Files 或模型，不返回凭据。
    private const string Dispatch = "SELECT fn_ai_knowledge_index_task.Id AS TaskId, fn_ai_knowledge_index_task.DocumentId, fn_ai_knowledge_index_task.VersionId, fn_ai_knowledge_index_task.DocumentVersion, fn_ai_knowledge_index_task.KnowledgeBaseVersion, fn_ai_knowledge_index_task.ModelConfigId, fn_ai_knowledge_index_task.ModelConfigVersion, fn_ai_knowledge_index_task.LeaseToken, fn_ai_knowledge_index_task.LeaseExpiresAtUtc, version.FileId, version.ContentHash, version.ContentType, version.SizeBytes, knowledge_snapshot.DataClassification, model_snapshot.ProviderKey AS ModelProviderKey, model_snapshot.ModelId, model_snapshot.EndpointBaseUrl AS ModelEndpointBaseUrl, model_snapshot.OrganizationId AS ModelOrganizationId FROM fn_ai_knowledge_index_task INNER JOIN fn_ai_knowledge_version AS version ON version.Id = fn_ai_knowledge_index_task.VersionId INNER JOIN fn_ai_knowledge_document AS document_snapshot ON document_snapshot.Id = fn_ai_knowledge_index_task.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge_snapshot ON knowledge_snapshot.Id = document_snapshot.KnowledgeBaseId INNER JOIN fn_ai_model_config AS model_snapshot ON model_snapshot.Id = fn_ai_knowledge_index_task.ModelConfigId WHERE fn_ai_knowledge_index_task.Id = @TaskId AND fn_ai_knowledge_index_task.StateKey = 'running' AND fn_ai_knowledge_index_task.LeaseToken = @LeaseToken AND fn_ai_knowledge_index_task.LeaseExpiresAtUtc > @Now" + OwnerExists;

    internal static readonly SqlStatement EnqueueHost = new("ai.knowledge_index_task.enqueue_host", Enqueue + Host + " AND " + Source, SqlDataScope.HostOnly);
    internal static readonly SqlStatement EnqueueTenant = new("ai.knowledge_index_task.enqueue_tenant", Enqueue + Tenant + " AND " + Source, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement AcquireHost = new("ai.knowledge_index_task.acquire_host", Acquire + Host + Live + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement AcquireTenant = new("ai.knowledge_index_task.acquire_tenant", Acquire + Tenant + Live + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement RenewHost = new("ai.knowledge_index_task.renew_host", Renew + Host + Live + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement RenewTenant = new("ai.knowledge_index_task.renew_tenant", Renew + Tenant + Live + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement FailHost = new("ai.knowledge_index_task.fail_host", Fail + Host + Live + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement FailTenant = new("ai.knowledge_index_task.fail_tenant", Fail + Tenant + Live + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement RetryHost = new("ai.knowledge_index_task.retry_host", Retry + Host + Live + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement RetryTenant = new("ai.knowledge_index_task.retry_tenant", Retry + Tenant + Live + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement CancelHost = new("ai.knowledge_index_task.cancel_host", Cancel + Host + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement CancelTenant = new("ai.knowledge_index_task.cancel_tenant", Cancel + Tenant + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement FindHost = new("ai.knowledge_index_task.find_host", Read + Host + " AND task.Id = @TaskId", SqlDataScope.HostOnly);
    internal static readonly SqlStatement FindTenant = new("ai.knowledge_index_task.find_tenant", Read + Tenant + " AND task.Id = @TaskId", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement FindBindingHost = new("ai.knowledge_index_task.binding_host", Read + Host + " AND task.VersionId = @VersionId AND task.DocumentVersion = @DocumentVersion AND task.KnowledgeBaseVersion = @KnowledgeBaseVersion", SqlDataScope.HostOnly);
    internal static readonly SqlStatement FindBindingTenant = new("ai.knowledge_index_task.binding_tenant", Read + Tenant + " AND task.VersionId = @VersionId AND task.DocumentVersion = @DocumentVersion AND task.KnowledgeBaseVersion = @KnowledgeBaseVersion", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static readonly SqlStatement DispatchHost = new("ai.knowledge_index_task.dispatch_host", Dispatch + Host + Live + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement DispatchTenant = new("ai.knowledge_index_task.dispatch_tenant", Dispatch + Tenant + Live + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
}
